using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
using MyDay.Windows.Core;
using MyDay.Windows.UI;
namespace MyDay.Windows
{
    internal static partial class Tests
    {
        private static void BlockTime(BlockGame g,double seconds){for(int i=0;i<(int)Math.Round(seconds*120);i++)g.Step(1.0/120);}
        private static int BlockCount(BlockGame g){int count=0;for(int y=0;y<MiniGameRules.BlocksRows;y++)for(int x=0;x<MiniGameRules.BlocksColumns;x++)if(g.CellAt(x,y)>0)count++;return count;}
        private static void BlockWell(BlockGame g,int rows,int column,int width){for(int y=MiniGameRules.BlocksRows-rows;y<MiniGameRules.BlocksRows;y++)for(int x=0;x<MiniGameRules.BlocksColumns;x++)g.SetCellForTest(x,y,x>=column&&x<column+width?0:5);}
        private static void RunBlocksTests(string directory)
        {
            var g=new BlockGame(7);Check(!g.Move(1)&&!g.Rotate(1)&&!g.HardDrop()&&g.State==SnackRoundState.Ready,"Blocks wait for an explicit start");
            Check(Enum.GetValues(typeof(BlockKind)).Cast<BlockKind>().All(k=>Enumerable.Range(0,4).All(r=>BlockGame.CellsFor(k,r).Distinct().Count()==4)&&BlockGame.CellsFor(k,0).SequenceEqual(BlockGame.CellsFor(k,4))),"Seven block shapes always contain four unique cells and rotate cyclically");
            g.Start();var sequence=new BlockKind[14];for(int i=0;i<14;i++){sequence[i]=g.Kind;g.HardDrop();g.ClearBoardForTest();}Check(sequence.Take(7).Distinct().Count()==7&&sequence.Skip(7).Distinct().Count()==7&&g.Next.Length>=3,"Seven-bag generation includes every shape once per bag and exposes next pieces");
            g.Start();g.SetPieceForTest(BlockKind.O,0,0,4);g.Move(-1);Check(!g.Move(-1)&&g.X==-1&&!g.Rotate(1),"Wall collision stops movement and square blocks never drift when rotated");
            g.SetPieceForTest(BlockKind.I,1,-2,4);Check(g.Rotate(1)&&g.Cells.All(c=>g.X+c.X>=0&&g.X+c.X<10),"A near-wall rotation kicks into the board without crossing the wall");g.SetPieceForTest(BlockKind.I,0,3,18);Check(g.Rotate(1)&&g.Cells.All(c=>g.Y+c.Y<20),"A floor rotation finds a bounded upward kick");
            g.Start();g.SetPieceForTest(BlockKind.T,0,3,5);for(int y=0;y<20;y++)for(int x=0;x<10;x++)g.SetCellForTest(x,y,1);foreach(var c in g.Cells)g.SetCellForTest(g.X+c.X,g.Y+c.Y,0);int oldX=g.X,oldY=g.Y;Check(!g.Rotate(1)&&g.X==oldX&&g.Y==oldY&&g.Rotation==0,"A blocked rotation leaves the piece and board unchanged");
            g.Start();g.SetPieceForTest(BlockKind.I,0,3,0);int ghost=g.GhostY;Check(g.SoftDrop()&&g.Score==1&&g.Y==1,"Soft drop advances one cell and scores only a real movement");g.HardDrop();Check(ghost==18&&BlockCount(g)==4&&g.Pieces==1&&g.Score==35&&Enumerable.Range(3,4).All(x=>g.CellAt(x,19)==1),"Hard drop locks exactly at its ghost position and scores actual distance");
            g.Start();g.SetPieceForTest(BlockKind.I,0,3,0);BlockWell(g,1,3,4);g.SetCellForTest(0,17,6);g.HardDrop();Check(g.Lines==1&&g.LastLinePoints==100&&g.Score==136&&g.CellAt(0,18)==6&&BlockCount(g)==1&&g.Flash>0,"A completed row clears once and the rows above collapse without losing colors");
            g.Start();BlockWell(g,4,5,1);g.SetPieceForTest(BlockKind.I,1,3,0);g.HardDrop();Check(g.Lines==4&&g.LastLinePoints==800&&g.Score==832&&BlockCount(g)==0,"Four simultaneous rows award eight hundred line points and leave an empty board");BlockWell(g,1,3,4);g.SetPieceForTest(BlockKind.I,0,3,0);g.HardDrop();Check(g.Lines==5&&g.Level==2&&g.LastLinePoints==100&&g.FallSeconds<MiniGameRules.BlocksFallSeconds,"Crossing five lines increases speed after awarding the prior level's points");BlockWell(g,1,3,4);g.SetPieceForTest(BlockKind.I,0,3,0);g.HardDrop();Check(g.LastLinePoints==200,"Subsequent line clears use the new level multiplier");
            g.Start();foreach(int row in new[]{17,19})for(int col=0;col<10;col++)if(col!=5)g.SetCellForTest(col,row,2);g.SetCellForTest(0,18,7);g.SetPieceForTest(BlockKind.I,1,3,0);g.HardDrop();Check(g.Lines==2&&g.LastLinePoints==300&&g.CellAt(0,19)==7&&g.CellAt(5,18)==1,"Nonadjacent full rows collapse in order without duplicating intermediate cells");
            var fuzz=new BlockGame(17);var rng=new MiniGameRandom(23);fuzz.Start();bool bounded=true;for(int i=0;i<1500;i++){if(fuzz.State==SnackRoundState.Finished)fuzz.Start();int action=rng.Next(5);if(action==0)fuzz.Move(-1);else if(action==1)fuzz.Move(1);else if(action==2)fuzz.Rotate(1);else if(action==3)fuzz.SoftDrop();else fuzz.HardDrop();fuzz.Step(.1);if(fuzz.State==SnackRoundState.Playing){foreach(var cell in fuzz.Cells){int px=fuzz.X+cell.X,py=fuzz.Y+cell.Y;bounded&=px>=0&&px<10&&py>=-4&&py<20&&(py<0||fuzz.CellAt(px,py)==0);}bounded&=fuzz.GhostY>=fuzz.Y&&fuzz.GhostY<20;}for(int row=0;row<20;row++)for(int col=0;col<10;col++)bounded&=fuzz.CellAt(col,row)>=0&&fuzz.CellAt(col,row)<=7;}Check(bounded,"A seeded mixed-input play session keeps active pieces, landing guides and board cells valid");
            g.Start();g.SetPieceForTest(BlockKind.I,0,3,18);BlockTime(g,.3);Check(g.Pieces==0,"A landed block allows a brief adjustment before locking");double age=g.Elapsed;g.Pause();BlockTime(g,2);Check(g.Elapsed==age&&g.Pieces==0&&!g.Move(1)&&!g.Rotate(1)&&!g.SoftDrop()&&!g.HardDrop(),"Pause freezes gravity, lock delay and every gameplay action");g.Resume();BlockTime(g,.12);Check(g.Pieces==1,"Resume continues the remaining lock delay instead of locking while paused");
            g.Start();g.SetPieceForTest(BlockKind.I,0,3,18);for(int i=0;i<22&&g.Pieces==0;i++){g.Move(i%2==0?-1:1);BlockTime(g,.3);}Check(g.Pieces==1,"Repeated floor movement has a bounded lock reset budget");
            g.Start();for(int y=0;y<2;y++)for(int x=3;x<7;x++)g.SetCellForTest(x,y,3);g.SetPieceForTest(BlockKind.I,0,0,18);g.HardDrop();Check(g.State==SnackRoundState.Finished&&!g.HardDrop(),"A blocked spawn ends the round and rejects further drops");
            g.Start();g.SetCellForTest(5,2,3);g.SetPieceForTest(BlockKind.I,1,3,-2);BlockTime(g,.5);Check(g.State==SnackRoundState.Finished&&BlockCount(g)==1,"Locking above the visible board ends safely without partial writes");
            var a=new BlockGame(9);var b=new BlockGame(9);a.Start();b.Start();for(int i=0;i<180;i++)a.Step(1.0/30);for(int i=0;i<720;i++)b.Step(1.0/120);Check(Math.Abs(a.Elapsed-b.Elapsed)<.001&&a.Y==b.Y&&a.X==b.X&&a.Kind==b.Kind&&a.Pieces==b.Pieces,"Block gravity and locking agree at thirty and one hundred twenty FPS");double valid=a.Elapsed;a.Step(double.NaN);a.Step(double.PositiveInfinity);a.Step(-1);Check(a.Elapsed==valid,"Invalid block frame times cannot corrupt the round");g.Start();Check(g.State==SnackRoundState.Playing&&g.Score==0&&g.Lines==0&&g.Pieces==0&&BlockCount(g)==0&&g.Level==1,"Restart resets board, score, level and the old result");
            string path=Path.Combine(directory,"blocks-best","scores.json");var records=new GameRecords(path);records.Record("bake",150);records.Record("blocks",1000);records.Record("blocks",10);var restored=new GameRecords(path);Check(restored.Best("blocks")==1000&&restored.Plays("blocks")==2&&restored.Best("bake")==150,"Block best scores persist alongside existing cooking records");
        }
        private static void BlockFrame(BlockGameWindow w,double seconds){for(int i=0;i<(int)Math.Round(seconds*120);i++)w.Advance(1.0/120);}
        public static void BlocksPreview(string directory)
        {
            Directory.CreateDirectory(directory);var records=new GameRecords();
            using(var art=new BlockArt())using(var tile=new Bitmap(96,96))using(var g=Graphics.FromImage(tile)){g.Clear(Color.Transparent);art.Tile(g,0,0,96,0,false);if(tile.GetPixel(0,0).A!=0||tile.GetPixel(48,48).A==0)throw new Exception("Sangmon block sprites lost their transparent silhouette");}
            using(var art=new BlockArt())using(var image=new Bitmap(960,600))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(246,245,235));MiniGameArt.Text(g,"상몬 블록 · 일곱 가지 모양",25,Design.Ink,35,22,true);for(int i=0;i<7;i++){int col=i<4?i:i-4,row=i<4?0:1;float x=40+col*230,y=110+row*240;MiniGameArt.Text(g,((BlockKind)i).ToString(),15,Design.Olive,x,y,true);foreach(var cell in BlockGame.CellsFor((BlockKind)i,0))art.Tile(g,x+cell.X*44,y+35+cell.Y*44,44,i,false);}image.Save(Path.Combine(directory,"windows-blocks-shapes.png"));}
            using(var hub=new GameHubWindow(records)){hub.Show();Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-blocks-hub.png"));}hub.ClientSize=Design.Size(740,600);Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-blocks-hub-compact.png"));}hub.Close();}
            using(var w=new BlockGameWindow(records)){
                w.Show();Application.DoEvents();w.VerifyFooterForTest();w.NativeKeyDownForTest(Keys.Space);if(w.Game.State!=SnackRoundState.Playing||w.Game.Pieces!=0)throw new Exception("Block native start performed an unintended hard drop");w.NativeKeyDownForTest(Keys.Space);if(w.Game.Pieces!=0)throw new Exception("Block start key repeat dropped the first piece");w.NativeKeyUpForTest(Keys.Space);w.Game.SetPieceForTest(BlockKind.T,0,3,4);var e=w.NativeKeyDownForTest(Keys.Right);if(!e.Handled||e.SuppressKeyPress)throw new Exception("Block input suppressed key releases");int x=w.Game.X;w.NativeKeyDownForTest(Keys.Right);if(w.Game.X!=x)throw new Exception("OS key repeat bypassed the block repeat timer");BlockFrame(w,.2);if(w.Game.X<=x)throw new Exception("Block held movement did not repeat");w.NativeKeyUpForTest(Keys.Right);x=w.Game.X;BlockFrame(w,.2);if(w.Game.X!=x)throw new Exception("Block key release left movement stuck");w.NativeKeyDownForTest(Keys.Up);w.NativeKeyUpForTest(Keys.Up);if(w.Game.Rotation!=1)throw new Exception("Block native rotation failed");w.NativeKeyDownForTest(Keys.Z);w.NativeKeyUpForTest(Keys.Z);if(w.Game.Rotation!=0)throw new Exception("Block counterclockwise rotation failed");
                w.NativeKeyDownForTest(Keys.Space);int pieces=w.Game.Pieces;w.NativeKeyDownForTest(Keys.Space);if(w.Game.Pieces!=pieces||pieces!=1)throw new Exception("Held Space hard dropped more than one piece");w.NativeKeyUpForTest(Keys.Space);w.NativeKeyDownForTest(Keys.Down);w.LoseFocusForTest();double time=w.Game.Elapsed;BlockFrame(w,1);if(w.Game.State!=SnackRoundState.Paused||w.Game.Elapsed!=time)throw new Exception("Block focus loss did not pause");w.TogglePause();int score=w.Game.Score;BlockFrame(w,.2);if(w.Game.Score!=score)throw new Exception("A stale down key remained active after resume");
                w.StartRound();w.Game.SetPieceForTest(BlockKind.T,0,3,4);for(int y=17;y<20;y++)for(int col=0;col<10;col++)if((col+y)%4!=0&&!(y==17&&col>5))w.Game.SetCellForTest(col,y,(col+y)%7+1);w.SavePreview(Path.Combine(directory,"windows-blocks.png"));using(var frame=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(directory,"windows-blocks-window.png"));}w.ClientSize=Design.Size(680,600);Application.DoEvents();w.VerifyFooterForTest();using(var frame=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(directory,"windows-blocks-window-compact.png"));}
                w.StartRound();BlockWell(w.Game,4,5,1);w.Game.SetPieceForTest(BlockKind.I,1,3,0);w.Pointer(new PointF(120,530));if(w.Game.Lines!=4||w.Game.Score!=832)throw new Exception("Block mouse drop or line clear failed");w.SavePreview(Path.Combine(directory,"windows-blocks-clear.png"));for(int y=0;y<2;y++)for(int col=3;col<7;col++)w.Game.SetCellForTest(col,y,3);w.Game.SetPieceForTest(BlockKind.I,0,0,18);w.NativeKeyDownForTest(Keys.Space);w.NativeKeyUpForTest(Keys.Space);w.Advance(.1);if(w.Game.State!=SnackRoundState.Finished||records.Plays("blocks")!=1||records.Best("blocks")!=832)throw new Exception("Block result was not saved exactly once");w.SavePreview(Path.Combine(directory,"windows-blocks-result.png"));MiniGameArt.WriteResult(Path.Combine(directory,"windows-blocks-card.png"),new MiniGameResult{Name="상몬 블록 쌓기",Day=DateTime.Today,Score=w.Game.Score,Details=w.Game.Lines+"줄 · 속도 Lv."+w.Game.Level});w.Close();
            }
            Console.WriteLine("Native blocks: six-game hub and compact buttons, key-up and timed repeat, rotation, single hard drop, focus pause, mouse drop, four-line clear, one record and PNG passed.");
        }
    }
}
